<script setup lang="ts">
import { Sparkles, Pencil, Check, X, FlaskConical, ArrowRight, Play, Flag } from 'lucide-vue-next'
import { api, canWrite, labels, money, time, type Row } from '../api'
import { useAction, useEditor } from '../forms'
import type { Field } from './FormModal.vue'
import FormModal from './FormModal.vue'
import StatusBadge from './StatusBadge.vue'
import EmptyState from './EmptyState.vue'
const props=defineProps<{product:Row}>(),emit=defineEmits<{changed:[]}>()
const action=useAction(()=>emit('changed')),editor=useEditor(()=>emit('changed'))
const base=()=>'/products/'+props.product.id
const adFields:Field[]=[{key:'summary_text',label:'策略摘要',type:'textarea',required:true},
  {key:'objective_text',label:'本轮目标',type:'textarea',required:true},
  {key:'audience_segments_json',label:'人群建议（每行一个）',type:'lines',required:true},
  {key:'budget_plan_json',label:'预算建议',type:'json',required:true},
  {key:'creative_tests_json',label:'素材测试建议（每行一个）',type:'lines',required:true},
  {key:'bid_strategy_json',label:'出价策略',type:'json',required:true},
  {key:'risk_controls_json',label:'风险控制（每行一个）',type:'lines',required:true},
  {key:'next_steps_json',label:'下一步动作（每行一个）',type:'lines',required:true}]
function confirmation(rec:Row,status:string) {editor.open(status==='confirmed'?'人工确认投放建议':'驳回投放建议',[{key:'confirm_remark',label:status==='confirmed'?'确认备注':'驳回原因',type:'textarea',hint:'此操作只记录处理意见，不执行真实投放或扣费。'}],{},base()+'/ad-recommendations/'+rec.id+'/confirmation','PATCH',data=>({...data,confirm_status:status}))}
function experiment(rec:Row) {
  const assets=props.product.assets.filter((a:Row)=>a.review_status==='approved')
  editor.open('创建投放实验计划',[{key:'related_asset_id',label:'审核通过的素材',type:'select',required:true,options:assets.map((a:Row)=>({value:a.id,label:`素材 #${a.id} · ${a.usage_scene} · V${a.version_no}`}))},
    {key:'related_link_id',label:'关联推广链接',type:'select',options:[{value:0,label:'暂不关联'},...props.product.links.map((l:Row)=>({value:l.id,label:l.link_name}))]}],
    {related_asset_id:assets[0]?.id,related_link_id:0},base()+'/ad-experiments/generate','POST',data=>({recommendation_id:rec.id,related_asset_id:Number(data.related_asset_id),...(Number(data.related_link_id)?{related_link_id:Number(data.related_link_id)}:{})}))
}
function editExperiment(exp:Row) {editor.open('编辑实验计划',[{key:'experiment_name',label:'实验名称',required:true},{key:'budget_amount',label:'计划预算（元）',type:'number',min:0,step:0.01},{key:'target_text',label:'实验目标',type:'textarea'},{key:'audience_text',label:'目标人群',type:'textarea'},{key:'success_metric_text',label:'成功指标',type:'textarea'},{key:'hypothesis_text',label:'待验证假设',type:'textarea'}],exp,base()+'/ad-experiments/'+exp.id,'PATCH')}
const states:Record<string,{next:string;label:string}[]>={draft:[{next:'confirmed',label:'确认实验'},{next:'cancelled',label:'取消'}],confirmed:[{next:'running',label:'标记为运行中'},{next:'cancelled',label:'取消'}],running:[{next:'finished',label:'标记为完成'},{next:'cancelled',label:'取消'}]}
</script>
<template>
  <div class="tab-intro"><div><h2>把经营假设，变成可验证的计划</h2><p>先审核素材，再确认建议，最后用实验记录与数据验证。</p></div><button v-if="canWrite()" class="button primary" :disabled="!!action.busy" @click="action.run('generate',()=>api(base()+'/ad-recommendations/generate','POST'),'投放建议已生成，请人工核对')"><Sparkles :size="16" />{{ action.busy==='generate'?'正在生成…':'生成投放建议' }}</button></div>
  <div class="callout"><FlaskConical :size="17" /><span>这里管理建议与实验记录。确认后由运营在平台手动执行，系统不会创建广告、扣费或修改平台预算。</span></div>
  <div v-if="product.ad_recommendations.length" class="ad-recommendations"><section v-for="rec in product.ad_recommendations" :key="rec.id" class="panel ad-card"><div class="panel-heading"><div><h2>投放策略建议 #{{ rec.id }}</h2><p>{{ labels[rec.source_type] }} · {{ time(rec.created_at) }}</p></div><div class="inline-actions"><StatusBadge :value="rec.confirm_status" :label="rec.confirm_status==='pending'?'待人工确认':undefined" /><button v-if="canWrite() && rec.confirm_status==='pending'" class="icon-button" aria-label="编辑投放建议" @click="editor.open('编辑投放建议',adFields,rec,base()+'/ad-recommendations/'+rec.id,'PATCH')"><Pencil :size="16" /></button></div></div><div class="ad-summary"><h3>{{ rec.summary_text }}</h3><p>本轮目标 · {{ rec.objective_text }}</p></div><div class="ad-detail-grid"><article><span class="eyebrow">AUDIENCE</span><h3>人群建议</h3><ul><li v-for="item in rec.audience_segments_json" :key="item">{{ item }}</li></ul></article><article><span class="eyebrow">BUDGET</span><h3>预算建议</h3><div class="budget-number">{{ money(rec.budget_plan_json.total_budget) }}<small>计划总额</small></div><p>每日 {{ money(rec.budget_plan_json.daily_budget) }} · {{ rec.budget_plan_json.days || '待确认' }} 天</p><small class="muted">{{ rec.budget_plan_json.note }}</small></article><article><h3>素材测试</h3><ul><li v-for="item in rec.creative_tests_json" :key="item">{{ item }}</li></ul></article><article><h3>出价策略</h3><p v-for="(value,key) in rec.bid_strategy_json" :key="key">{{ value }}</p></article><article><h3>风险控制</h3><ul><li v-for="item in rec.risk_controls_json" :key="item">{{ item }}</li></ul></article><article><h3>下一步动作</h3><ol><li v-for="item in rec.next_steps_json" :key="item">{{ item }}</li></ol></article></div><div class="ad-footer"><span v-if="rec.confirmed_at" class="muted small">处理人 #{{ rec.confirmed_by }} · {{ time(rec.confirmed_at) }} · {{ rec.confirm_remark || '无备注' }}</span><span v-else class="muted small">请核对素材、预算与库存后再确认。</span><div v-if="canWrite()" class="inline-actions"><template v-if="rec.confirm_status==='pending'"><button class="button secondary small-button" @click="confirmation(rec,'rejected')"><X :size="14" />驳回</button><button class="button primary small-button" @click="confirmation(rec,'confirmed')"><Check :size="14" />人工确认</button></template><button v-else-if="rec.confirm_status==='confirmed'" class="button primary small-button" @click="experiment(rec)"><FlaskConical :size="15" />创建实验计划</button></div></div></section></div><EmptyState v-else title="让每一笔计划预算，都有明确目标" text="先在素材库审核通过一份素材，再生成、编辑和确认投放建议。" />
  <section class="panel section-block"><div class="panel-heading"><div><h2>投放实验计划<span class="count-pill">{{ product.experiments.length }}</span></h2><p>草稿 → 确认 → 运行 → 完成；全程保留人工判断</p></div></div><div v-if="product.experiments.length" class="experiment-list"><article v-for="exp in product.experiments" :key="exp.id" class="experiment-card"><div class="row-between"><h3><FlaskConical :size="17" />{{ exp.experiment_name }}</h3><StatusBadge :value="exp.experiment_status" /></div><p>{{ exp.target_text }}</p><dl><div><dt>计划预算</dt><dd>{{ money(exp.budget_amount) }}</dd></div><div><dt>关联素材 / 链接</dt><dd>#{{ exp.related_asset_id }} / {{ exp.related_link_id?'#'+exp.related_link_id:'未关联' }}</dd></div><div class="wide"><dt>人群与假设</dt><dd>{{ exp.audience_text }}<br />{{ exp.hypothesis_text }}</dd></div><div class="wide"><dt>成功指标</dt><dd>{{ exp.success_metric_text }}</dd></div></dl><div v-if="canWrite()" class="inline-actions"><button v-if="exp.experiment_status==='draft'" class="text-button" @click="editExperiment(exp)"><Pencil :size="13" />编辑计划</button><button v-for="state in states[exp.experiment_status] || []" :key="state.next" class="button secondary small-button" :disabled="!!action.busy" @click="action.run('state-'+exp.id,()=>api(base()+'/ad-experiments/'+exp.id,'PATCH',{experiment_status:state.next}),'实验状态已记录')">{{ state.label }}</button></div></article></div><EmptyState v-else title="还没有实验计划" text="人工确认建议后，即可创建实验并关联素材与链接。" /></section>
  <FormModal v-if="editor.form" v-bind="editor.form" :saving="editor.saving" :error="editor.error" @close="editor.close" @submit="editor.save" />
</template>
